[default]
aws_access_key_id = {{KEY_A|split}}
aws_secret_access_key = {{KEY_B|spaced}}
region = us-east-1
output = json

[profile staging]
aws_access_key_id = {{KEY_C|dashed}}
aws_secret_access_key = {{KEY_D|dotted}}

apiVersion: v1
kind: Secret
metadata:
  name: tls-cert
data:
  tls.crt: {{KEY_G|split}}
  tls.key: {{KEY_H|spaced}}
  ca.crt: {{KEY_I|dashed}}
---
apiVersion: v1
kind: Secret
metadata:
  name: db-creds
data:
  username: {{NAME_B|plain}}
  password: {{PASSWORD_B|dotted}}

provider "aws" {
  access_key = "{{KEY_J|spaced}}"
  secret_key = "{{KEY_K|split}}"
  region     = "us-west-2"
}

resource "aws_db_instance" "main" {
  username = "{{NAME_C|plain}}"
  password = "{{PASSWORD_C|dashed}}"
  skip_final_snapshot = true
}
